28	type DialogState = 'choosing' | 'waiting' | 'complete' | 'error';
29	
30	export function ValidationDialog({
31	  validationLink,
32	  learnMoreUrl,
33	  onChoice,
34	}: ValidationDialogProps): React.JSX.Element {
35	  const [state, setState] = useState<DialogState>('choosing');
36	  const [errorMessage, setErrorMessage] = useState<string>('');
37	
38	  const items = [
39	    {
40	      label: 'Verify your account',
41	      value: 'verify' as const,
42	      key: 'verify',
43	    },
44	    {
45	      label: 'Change authentication',
46	      value: 'change_auth' as const,
47	      key: 'change_auth',
48	    },
49	  ];
50	
51	  // Handle keypresses globally for cancellation, and specific logic for waiting state
52	  useKeypress(
53	    (key) => {
54	      if (keyMatchers[Command.ESCAPE](key) || keyMatchers[Command.QUIT](key)) {
55	        onChoice('cancel');
56	        return true;
57	      } else if (state === 'waiting' && keyMatchers[Command.RETURN](key)) {
58	        // User confirmed verification is complete - transition to 'complete' state
59	        setState('complete');
60	        return true;
61	      }
62	      return false;
63	    },
64	    { isActive: state !== 'complete' },
65	  );
66	
67	  // When state becomes 'complete', show success message briefly then proceed
68	  useEffect(() => {
69	    if (state === 'complete') {
70	      const timer = setTimeout(() => {
71	        onChoice('verify');
72	      }, 500);
73	      return () => clearTimeout(timer);
74	    }
75	    return undefined;
76	  }, [state, onChoice]);
77	
78	  const handleSelect = useCallback(
79	    async (choice: ValidationIntent) => {
80	      if (choice === 'verify') {
81	        if (validationLink) {
82	          // Check if we're in an environment where we can launch a browser
83	          if (!shouldLaunchBrowser()) {
84	            // In headless mode, show the link and wait for user to manually verify
85	            setErrorMessage(
86	              `Please open this URL in a browser: ${validationLink}`,
87	            );
88	            setState('waiting');
89	            return;
90	          }
91	
92	          try {
93	            await openBrowserSecurely(validationLink);
94	            setState('waiting');
95	          } catch (error) {
96	            setErrorMessage(
97	              error instanceof Error ? error.message : 'Failed to open browser',
98	            );
99	            setState('error');
100	          }
101	        } else {
102	          // No validation link, just retry
103	          onChoice('verify');
104	        }
105	      } else {
106	        // 'change_auth' or 'cancel'
107	        onChoice(choice);
108	      }
109	    },
110	    [validationLink, onChoice],
111	  );
112	
113	  if (state === 'error') {
114	    return (
115	      <Box borderStyle="round" flexDirection="column" padding={1}>
116	        <Text color={theme.status.error}>
117	          {errorMessage ||
118	            'Failed to open verification link. Please try again or change authentication.'}
119	        </Text>
120	        <Box marginTop={1}>
121	          <RadioButtonSelect
122	            items={items}
123	            onSelect={(choice) => void handleSelect(choice as ValidationIntent)}
124	          />
125	        </Box>
126	      </Box>
127	    );
128	  }
129	
130	  if (state === 'waiting') {
131	    return (
132	      <Box borderStyle="round" flexDirection="column" padding={1}>
133	        <Box>
134	          <CliSpinner />
135	          <Text>
136	            {' '}
137	            Waiting for verification... (Press ESC or CTRL+C to cancel)
138	          </Text>
139	        </Box>
140	        {errorMessage && (
141	          <Box marginTop={1}>
142	            <Text>{errorMessage}</Text>
143	          </Box>
144	        )}
145	        <Box marginTop={1}>
146	          <Text dimColor>Press Enter when verification is complete.</Text>
147	        </Box>
148	      </Box>
149	    );
150	  }
151	
152	  if (state === 'complete') {
153	    return (
154	      <Box borderStyle="round" flexDirection="column" padding={1}>
155	        <Text color={theme.status.success}>Verification complete</Text>
156	      </Box>
157	    );
158	  }
159	
160	  return (
161	    <Box borderStyle="round" flexDirection="column" padding={1}>
162	      <Box marginBottom={1}>
163	        <Text>Further action is required to use this service.</Text>
164	      </Box>
165	      <Box marginTop={1} marginBottom={1}>
166	        <RadioButtonSelect
167	          items={items}
168	          onSelect={(choice) => void handleSelect(choice as ValidationIntent)}
169	        />
170	      </Box>
171	      {learnMoreUrl && (
172	        <Box marginTop={1}>
173	          <Text dimColor>
174	            Learn more: <Text color={theme.text.accent}>{learnMoreUrl}</Text>
175	          </Text>
176	        </Box>
177	      )}
178	    </Box>
179	  );
180	}
