7	import type { Key } from './hooks/useKeypress.js';
8	import type { KeyBinding, KeyBindingConfig } from '../config/keyBindings.js';
9	import { Command, defaultKeyBindings } from '../config/keyBindings.js';
10	
11	/**
12	 * Matches a KeyBinding against an actual Key press
13	 * Pure data-driven matching logic
14	 */
15	function matchKeyBinding(keyBinding: KeyBinding, key: Key): boolean {
16	  // Check modifiers - follow original logic:
17	  // undefined = ignore this modifier (original behavior)
18	  // true = modifier must be pressed
19	  // false = modifier must NOT be pressed
20	  return (
21	    keyBinding.key === key.name &&
22	    (keyBinding.shift === undefined || key.shift === keyBinding.shift) &&
23	    (keyBinding.alt === undefined || key.alt === keyBinding.alt) &&
24	    (keyBinding.ctrl === undefined || key.ctrl === keyBinding.ctrl) &&
25	    (keyBinding.cmd === undefined || key.cmd === keyBinding.cmd)
26	  );
27	}
28	
29	/**
30	 * Checks if a key matches any of the bindings for a command
31	 */
32	function matchCommand(
33	  command: Command,
34	  key: Key,
35	  config: KeyBindingConfig = defaultKeyBindings,
36	): boolean {
37	  const bindings = config[command];
38	  return bindings.some((binding) => matchKeyBinding(binding, key));
39	}
40	
41	/**
42	 * Key matcher function type
43	 */
44	type KeyMatcher = (key: Key) => boolean;
45	
46	/**
47	 * Type for key matchers mapped to Command enum
48	 */
49	export type KeyMatchers = {
50	  readonly [C in Command]: KeyMatcher;
51	};
52	
53	/**
54	 * Creates key matchers from a key binding configuration
55	 */
56	export function createKeyMatchers(
57	  config: KeyBindingConfig = defaultKeyBindings,
58	): KeyMatchers {
59	  // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
60	  const matchers = {} as { [C in Command]: KeyMatcher };
61	
62	  for (const command of Object.values(Command)) {
63	    matchers[command] = (key: Key) => matchCommand(command, key, config);
64	  }
65	
66	  return matchers as KeyMatchers;
67	}
68	
69	/**
70	 * Default key binding matchers using the default configuration
71	 */
72	export const keyMatchers: KeyMatchers = createKeyMatchers(defaultKeyBindings);
73	
74	// Re-export Command for convenience
75	export { Command };
