import type React from 'react';
import { useMemo, useState } from 'react';
import { Box, Text } from 'ink';
import { theme } from '../semantic-colors.js';
import { useKeypress } from '../hooks/useKeypress.js';
import { keyMatchers, Command } from '../keyMatchers.js';

/**
 * A single hook entry rendered by {@link HooksDialog}.
 */
export interface HookEntry {
  config: {
    name?: string;
    command?: string;
    type?: string;
    description?: string;
    timeout?: number;
  };
  source: string;
  eventName: string;
  matcher?: string;
  sequential?: boolean;
  enabled: boolean;
}

interface HooksDialogProps {
  hooks: HookEntry[];
  onClose: () => void;
  /**
   * Maximum number of hooks to render at once. When there are more hooks than
   * this, the list becomes scrollable and scroll indicators are shown.
   */
  maxVisibleHooks?: number;
}

/**
 * Resolve the display name for a hook, falling back to its command when no
 * explicit name is configured.
 */
function getHookDisplayName(hook: HookEntry): string {
  return hook.config.name || hook.config.command || 'unknown';
}

/**
 * An interactive dialog for browsing configured hooks. Unlike the previous
 * message-feed rendering, this component owns its own key handling: it can be
 * scrolled and dismissed independently of the conversation history.
 */
export const HooksDialog: React.FC<HooksDialogProps> = ({
  hooks,
  onClose,
  maxVisibleHooks,
}) => {
  const [scrollOffset, setScrollOffset] = useState(0);

  const total = hooks.length;
  const windowSize =
    maxVisibleHooks && maxVisibleHooks > 0 ? maxVisibleHooks : total;
  const maxOffset = Math.max(0, total - windowSize);
  // Guard against a stale offset if the list ever shrinks.
  const clampedOffset = Math.min(scrollOffset, maxOffset);

  const showScrollUp = clampedOffset > 0;
  const showScrollDown = clampedOffset < maxOffset;

  useKeypress(
    (key) => {
      if (keyMatchers[Command.ESCAPE](key)) {
        onClose();
        return;
      }
      if (keyMatchers[Command.NAVIGATION_UP](key)) {
        setScrollOffset((offset) => Math.max(0, offset - 1));
        return;
      }
      if (keyMatchers[Command.NAVIGATION_DOWN](key)) {
        setScrollOffset((offset) => Math.min(maxOffset, offset + 1));
        return;
      }
    },
    { isActive: true },
  );

  // The visible slice of hooks, re-grouped by event name for display.
  const visibleHooksByEvent = useMemo(() => {
    const visible = hooks.slice(clampedOffset, clampedOffset + windowSize);
    return visible.reduce(
      (acc, hook) => {
        if (!acc[hook.eventName]) {
          acc[hook.eventName] = [];
        }
        acc[hook.eventName].push(hook);
        return acc;
      },
      {} as Record<string, HookEntry[]>,
    );
  }, [hooks, clampedOffset, windowSize]);

  return (
    <Box borderStyle="round" flexDirection="column" padding={1}>
      <Box flexDirection="column">
        <Text color={theme.status.warning} bold underline>
          ⚠️ Security Warning:
        </Text>
        <Text color={theme.status.warning}>
          Hooks can execute arbitrary commands on your system. Only use hooks
          from sources you trust. Review hook scripts carefully.
        </Text>
      </Box>

      <Box marginTop={1}>
        <Text>
          Learn more:{' '}
          <Text color={theme.text.link}>https://geminicli.com/docs/hooks</Text>
        </Text>
      </Box>

      <Box marginTop={1}>
        <Text bold>Configured Hooks:</Text>
      </Box>

      {total === 0 ? (
        <Box paddingLeft={2} marginTop={1}>
          <Text>No hooks configured.</Text>
        </Box>
      ) : (
        <Box flexDirection="column" paddingLeft={2} marginTop={1}>
          {showScrollUp && <Text color={theme.text.secondary}>▲</Text>}
          {Object.entries(visibleHooksByEvent).map(([eventName, eventHooks]) => (
            <Box key={eventName} flexDirection="column" marginBottom={1}>
              <Text color={theme.text.accent} bold>
                {eventName}:
              </Text>
              <Box flexDirection="column" paddingLeft={2}>
                {eventHooks.map((hook, index) => {
                  const hookName = getHookDisplayName(hook);
                  const statusColor = hook.enabled
                    ? theme.status.success
                    : theme.text.secondary;
                  const statusText = hook.enabled ? 'enabled' : 'disabled';

                  return (
                    <Box
                      key={`${eventName}-${index}`}
                      flexDirection="column"
                    >
                      <Box>
                        <Text>
                          <Text color={theme.text.accent}>{hookName}</Text>
                          <Text
                            color={statusColor}
                          >{` [${statusText}]`}</Text>
                        </Text>
                      </Box>
                      <Box paddingLeft={2} flexDirection="column">
                        {hook.config.description && (
                          <Text italic>{hook.config.description}</Text>
                        )}
                        <Text dimColor>
                          Source: {hook.source}
                          {hook.config.name &&
                            hook.config.command &&
                            ` | Command: ${hook.config.command}`}
                          {hook.matcher && ` | Matcher: ${hook.matcher}`}
                          {hook.sequential && ` | Sequential`}
                          {hook.config.timeout &&
                            ` | Timeout: ${hook.config.timeout}s`}
                        </Text>
                      </Box>
                    </Box>
                  );
                })}
              </Box>
            </Box>
          ))}
          {showScrollDown && <Text color={theme.text.secondary}>▼</Text>}
        </Box>
      )}

      <Box marginTop={1} flexDirection="column">
        <Text dimColor>
          Tip: Use <Text bold>/hooks enable {'<hook-name>'}</Text> or{' '}
          <Text bold>/hooks disable {'<hook-name>'}</Text> to toggle individual
          hooks. Use <Text bold>/hooks enable-all</Text> or{' '}
          <Text bold>/hooks disable-all</Text> to toggle all hooks at once.
        </Text>
        <Text dimColor>
          Use ↑/↓ to scroll and Esc to close.
        </Text>
      </Box>
    </Box>
  );
};
